<script>document.querySelectorAll('[data-upload]').forEach(function(root){var input=root.querySelector('[data-upload-input]'),zone=root.querySelector('[data-upload-zone]'),name=root.querySelector('[data-upload-name]'),preview=root.querySelector('[data-upload-preview]');if(!input||!zone)return;['dragenter','dragover'].forEach(function(type){zone.addEventListener(type,function(e){e.preventDefault();zone.classList.add('is-dragging')})});['dragleave','drop'].forEach(function(type){zone.addEventListener(type,function(e){e.preventDefault();zone.classList.remove('is-dragging')})});zone.addEventListener('drop',function(e){if(e.dataTransfer.files.length){input.files=e.dataTransfer.files;input.dispatchEvent(new Event('change'))}});input.addEventListener('change',function(){var file=input.files[0];if(!file)return;name.textContent=file.name+' · '+Math.ceil(file.size/1024)+' KB';if(file.type.indexOf('image/')===0){var reader=new FileReader();reader.onload=function(){preview.innerHTML='<img src="'+reader.result+'" alt="Preview upload">'};reader.readAsDataURL(file)}})});</script>
